{"implementation": "import math
def solve(case):
    sentence_vectors = case["sentence_vectors"]
    query_vector = case["query_vector"]
    context_weight = case["context_weight"]
    n = len(sentence_vectors)
    if n == 0:
        return {"ranking": [], "scores": []}
    def norm(v):
        return math.sqrt(sum(x*x for x in v))
    query_norm = norm(query_vector)
    if query_norm == 0:
        query_norm = 1e-10
    vec_len = len(query_vector)
    context = [0.0] * vec_len
    for sv in sentence_vectors:
        for i in range(vec_len):
            context[i] += sv[i]
    context = [x / n for x in context]
    context_norm = norm(context)
    if context_norm == 0:
        context_norm = 1e-10
    scores = []
    for sv in sentence_vectors:
        sv_norm = norm(sv)
        if sv_norm == 0:
            sv_norm = 1e-10
        dot_q = sum(a*b for a,b in zip(sv, query_vector))
        cos_q = dot_q / (sv_norm * query_norm)
        dot_c = sum(a*b for a,b in zip(sv, context))
        cos_c = dot_c / (sv_norm * context_norm)
        score = (1 - context_weight) * cos_q + context_weight * cos_c
        scores.append(score)
    indices = list(range(n))
    indices.sort(key=lambda i: scores[i], reverse=True)
    return {"ranking": indices, "scores": scores}"}
